use std::io::{self, Read, Cursor};
use std::collections::HashMap;
use flate2::read::GzDecoder;
use sha2::{Sha256, Digest};
use hmac::{Hmac, Mac};

type HmacSha256 = Hmac<Sha256>;

const MAX_UPLOAD_SIZE: u64 = 10 * 1024 * 1024; // 10MB compressed
const MAX_DECOMPRESSED_SIZE: u64 = 50 * 1024 * 1024; // 50MB absolute max
const CHUNK_SIZE: usize = 8192;

#[derive(Debug)]
pub struct AuthToken {
    pub user_id: String,
    pub permissions: Vec<String>,
    pub signature: Vec<u8>,
}

#[derive(Debug)]
pub struct CertificateBundle {
    pub token: AuthToken,
    pub payload: Vec<u8>,
}

pub struct AuthProcessor {
    hmac_key: Vec<u8>,
    session_store: HashMap<String, CertificateBundle>,
    global_decompression_budget: u64,
}

impl AuthProcessor {
    pub fn new(key: &[u8]) -> Self {
        AuthProcessor {
            hmac_key: key.to_vec(),
            session_store: HashMap::new(),
            global_decompression_budget: MAX_DECOMPRESSED_SIZE,
        }
    }

    fn verify_signature(&self, token: &AuthToken, data: &[u8]) -> bool {
        let mut mac = HmacSha256::new_from_slice(&self.hmac_key)
            .expect("HMAC key length issue");
        mac.update(token.user_id.as_bytes());
        mac.update(data);
        mac.verify_slice(&token.signature).is_ok()
    }

    fn safe_decompress(&self, data: &[u8], remaining_budget: &mut u64) -> io::Result<Vec<u8>> {
        let compressed_size = data.len() as u64;

        if compressed_size > MAX_UPLOAD_SIZE {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "Upload exceeds maximum compressed size",
            ));
        }

        let mut decoder = GzDecoder::new(Cursor::new(data));
        let mut output = Vec::new();
        let mut total_read: u64 = 0;
        let mut buf = [0u8; CHUNK_SIZE];

        loop {
            match decoder.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    total_read += n as u64;
                    // Check against shared remaining budget (tracks across all nested layers)
                    if total_read > *remaining_budget {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidData,
                            "Global decompression budget exceeded",
                        ));
                    }
                    output.extend_from_slice(&buf[..n]);
                }
                Err(e) => return Err(e),
            }
        }

        // Deduct from remaining budget
        *remaining_budget = remaining_budget.saturating_sub(total_read);

        Ok(output)
    }

    pub fn process_certificate_upload(
        &mut self,
        user_id: &str,
        compressed_payload: &[u8],
        signature: &[u8],
        permissions: Vec<String>,
    ) -> Result<String, String> {
        let token = AuthToken {
            user_id: user_id.to_string(),
            permissions,
            signature: signature.to_vec(),
        };

        let mut budget = self.global_decompression_budget;

        // First decompress to validate structure
        let payload = self.safe_decompress(compressed_payload, &mut budget)
            .map_err(|e| format!("Decompression failed: {}", e))?;

        // Verify signature over decompressed payload
        if !self.verify_signature(&token, &payload) {
            return Err("Invalid signature".to_string());
        }

        // Process nested certificates with shared budget
        let final_payload = self.process_nested_certificates(&payload, &mut budget)?;

        let session_id = self.generate_session_id(&token);
        let bundle = CertificateBundle {
            token,
            payload: final_payload,
        };

        self.session_store.insert(session_id.clone(), bundle);
        Ok(session_id)
    }

    fn process_nested_certificates(&self, data: &[u8], budget: &mut u64) -> Result<Vec<u8>, String> {
        // Certificate format: first 4 bytes = magic, next 4 = nested count
        if data.len() < 8 {
            return Ok(data.to_vec());
        }

        let magic = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
        if magic != 0x43455254 { // "CERT"
            return Ok(data.to_vec());
        }

        let nested_count = u32::from_le_bytes([data[4], data[5], data[6], data[7]]) as usize;

        // Limit nesting depth
        if nested_count > 16 {
            return Err("Too many nested certificates".to_string());
        }

        let mut offset = 8usize;
        let mut combined = Vec::new();

        for _ in 0..nested_count {
            if offset + 4 > data.len() {
                break;
            }
            let chunk_len = u32::from_le_bytes([
                data[offset], data[offset+1], data[offset+2], data[offset+3]
            ]) as usize;
            offset += 4;

            if offset + chunk_len > data.len() {
                return Err("Malformed nested certificate".to_string());
            }

            let chunk = &data[offset..offset + chunk_len];
            // Each nested cert is also gzip compressed - decompress with shared budget
            let decompressed = self.safe_decompress(chunk, budget)
                .map_err(|e| format!("Nested decompression failed: {}", e))?;
            combined.extend_from_slice(&decompressed);
            offset += chunk_len;
        }

        Ok(combined)
    }

    fn generate_session_id(&self, token: &AuthToken) -> String {
        let mut hasher = Sha256::new();
        hasher.update(token.user_id.as_bytes());
        hasher.update(&token.signature);
        hasher.update(std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()
            .to_le_bytes());
        format!("{:x}", hasher.finalize())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_flow() {
        let processor = AuthProcessor::new(b"test-key-32-bytes-long-enough!!");
        let mut budget = MAX_DECOMPRESSED_SIZE;
        let data = vec![0u8; 100];
        let result = processor.safe_decompress(&data, &mut budget);
        // Invalid gzip will error
        assert!(result.is_err());
    }
}
